package dao;
import database.DBConnection; import model.CartItem; import org.springframework.stereotype.Repository; import java.sql.*; import java.util.*;
@Repository public class OrderDAO {
 public int createOrder(String name,double total,List<CartItem> items,String method,String status){String customer="SELECT customer_id FROM Customer WHERE customer_name=? LIMIT 1";String order="INSERT INTO Orders(customer_id,climate_id,total_amount,payment_method,payment_status,order_status) VALUES(?,NULL,?,?,?,?)";String item="INSERT INTO Order_Items(order_id,food_id,quantity,price) VALUES(?,?,?,?)";Connection c=null;try{c=DBConnection.getConnection();c.setAutoCommit(false);int cid;try(PreparedStatement p=c.prepareStatement(customer)){p.setString(1,name);try(ResultSet r=p.executeQuery()){if(!r.next()){c.rollback();return 0;}cid=r.getInt(1);}}int oid;try(PreparedStatement p=c.prepareStatement(order,Statement.RETURN_GENERATED_KEYS)){p.setInt(1,cid);p.setDouble(2,total);p.setString(3,method);p.setString(4,status);p.setString(5,"Placed");p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){if(!r.next()){c.rollback();return 0;}oid=r.getInt(1);}}try(PreparedStatement p=c.prepareStatement(item)){for(CartItem i:items){p.setInt(1,oid);p.setInt(2,i.getFoodId());p.setInt(3,i.getQuantity());p.setDouble(4,i.getFood().getPrice());p.addBatch();}p.executeBatch();}c.commit();return oid;}catch(Exception e){e.printStackTrace();try{if(c!=null)c.rollback();}catch(Exception ignored){}return 0;}finally{try{if(c!=null)c.close();}catch(Exception ignored){}}}
}
